#include <iostream>
inline int square(int x) { return x * x; }   // 参数只求值一次，且有类型检查
int main() {
  int x = 2;
  int m = square(x++);   // x 只自增一次：m=4, x=3
  std::cout << m << ' ' << x << '\n';
}
